  [21986] = { "Blackrock DepthsのArenaでこの旗を使い、Theldrenに挑戦します。", 0x9116746d, "u" },
  [21987] = { "まだくすぶっているLord Incendiusのこの塊は、極上の石炭になるだろう。", 0x3c7e822c, "u" },
  [21988] = { "これは熱すぎて触れない……燃えないもので包んだほうがいい！", 0xb18e73a9, "u" },
  [21989] = { "この公爵の生々しい塊は、あなたへの憎しみを糧に燃え続けている。", 0x1bdd9c3f, "u" },
})
